def superusers_become_admins(apps, schema_editor):
    """Whoever administered the platform yesterday still does today.

    Administration used to be ``is_superuser`` sitting on top of another role.
    Now it is a role, and it is the only source of ``user.manage`` - so without
    this step the people who could manage staff on Friday cannot on Monday, and
    nobody can promote them back.

    ``is_senior`` is cleared with it: the database refuses seniority on anything
    but a CSM, and this bypasses the model's save().
    """
    User = apps.get_model("users", "User")
    User.objects.filter(is_superuser=True).update(role="ADMIN", is_senior=False)


